  ('0d6d6ae1-a6df-5db3-a940-ac45ba9e83ca', '0bde26c6-5330-54d5-a96e-c5a867ce7481', 1, 'ለመዘምራን አለቃ በበገናዎች የዳዊት ትምህርት።'),
  ('a7105d0b-7c3a-5671-a7b9-f8e7bc506ffc', '980a59d5-d40f-540f-a5f0-f7fbc940cd96', 1, 'ለመዘምራን አለቃ ከቅዱሳን ስለ ራቁ ሕዝብ ፍልስጥኤማውያን በጌት በያዙት ጊዜ የዳዊት ቅኔ።'),
