  ('3c2e0ff5-acae-5f73-a374-a7356c4f7a88', '46c37a6b-268c-56b6-af33-3d343f0b4b4f', 1, 'ለመዘምራን አለቃ አታጥፋ። የዳዊት ቅኔ።'),
