VALUES
  ('9dc3e748-75f3-51ae-a243-f3ab716dd3e0', '75019e15-5dc0-58f9-a044-f5780ae0fcc8', 1, 'ምዕራፍ ፲ ከጴጥሮስ ለውሉደ ክርስቲያን የተሠጠ ተግሣፅና ምክር'),
  ('c23e93a9-544b-580d-aa18-f880a77c07f6', '12bbf89b-3c11-565f-a5ec-13dc8b62325b', 1, 'ምዕራፍ ፲፩ ስለመድሐኒታችን ስውመሆንና ስለዳግም ምፅአቱ ስለሌሎችም የቤተክርስቲያን ሥርዓቶች'),
  ('fe781be7-7a55-562a-a8fd-9ec6bfefd777', '69f47165-ee4e-57f0-a19c-b3f0d97605c7', 1, 'ምዕራፍ ፲፪ ስለካህናት ፅናት'),
  ('8f64219b-8140-517c-a1d3-77a25c8de42b', '8377ae17-37d8-5410-a023-b06e4cea890e', 1, 'የቅዱሳን ፡ አበው ፡ ሐዋርያት ፡ ትምህርት ፡ ዲድስቅልያ ። ጸሎታቸውና ፡ በረከታቸው ፡ ከእኛ ፡ ጋር ፡ ይኑር ። ሁሉን ፡ በያዘ ፡ በእግዚአብሔር ፡ አብ ፡ በአንድ ፡ ልጁ ፡ በኢየሱስ ፡ ክርስቶስ ፡ ናዛዚ ፡ በሚሆን ፡ በመንፈስ ፡ ቅዱስ ፡ ስም ።'),
  ('5e278055-0387-5680-ae31-a6e1907a3e11', '5f1322c2-d2e5-55da-a38b-c6cf3440dd78', 1, 'በመንፈስ ፡ ቅዱስ ፡ ኃይል ፡ ከመጻሕፍት ፡ የተገኘውን ፡ ጥቅም ፡ ማወቅን ፡ ሁለ ፡ ጊዜ ፡ ይመረምሩ ፡ ዘንድ ፡ ለባለ ፡ ጸጎች ፡ እንደሚገባ ፡ ይናገራል ።'),
  ('707ed58b-7f05-5509-a8e8-eb7bd03668f5', '86c9e34d-1885-52c5-a595-6a9cff087fad', 1, 'ሴቶች ፡ ለባሎቻቸው ፡ ይታዘዙ ፡ ዘንድ ፣ ፡ በቀናም ፡ ጥበብ ፡ ጸንተው ፡ ይኖሩ ፡ ዘንድ ፡ እንዲገባ ፡ ይናገራል ።'),
  ('79b16f8e-9c75-5f79-a161-416b208b607d', '55adff54-76f0-5571-ab4f-23871210bb68', 1, 'ስለ ፡ ኤጲስ ፡ ቆጶስ ፣ ፡ ስለ ፡ ቄስና ፡ ስለ ፡ ዲያቆናት ፡ ይናገራል ።'),
  ('5022a690-7d14-5084-a616-20a285c59001', 'a280ebcd-5900-50a0-a129-e4b6b36ea8b4', 1, 'ኤጲስ ፡ ቆጶሱ ፡ የነገር ፡ ሥራን ፡ መስማት ፡ እንደማይገባው ፡ ይናገራል ።'),
  ('e40bdb06-55c0-51a6-aff0-b4e2daacaffa', 'e60771ff-3e96-5265-a613-644bbc7baf1b', 1, 'ኤጲስ ፡ ቆጶሳት ፡ በፍቅርና ፣ ፡ በቅንነት ፡ የሚመለሱትን ፡ ንስሐቸውን ፡ ይቀበሉ ።'),
  ('88e98b22-01de-52ed-a18c-80e7345a43a9', 'd3b47493-b2bd-599a-a396-8f9b197456ab', 1, 'እንደ ፡ በደለ ፡ ሳያስመሰክሩ ፡ ማን ፡ ንም ፡ እንቀጣ ፡ ዘንድ ፡ እንዳይገባ ፡ ይናገራል ።'),
  ('0ce060fa-e592-5d7a-af5d-0b84f8e2b351', 'aa224e0d-ce4d-5b2f-a94e-e9b50c5d62bf', 1, 'ሕዝቡ ፡ ያላቸውን ፡ ያህል ፡ ለቤተ ፡ ክርስቲያን ፡ መባእ ፡ ያገቡ ፡ ዘንድ ፡ የሚገባቸው ፡ ስለሆነ ፡ ይናገራል ።'),
  ('a10eb387-1ecd-535b-aa58-ed7ca82b5afa', 'e86bb63d-0a27-5c02-a6f1-cad3d11dbb4f', 1, 'ዲያቆኑ ፡ ያለ ፡ ኤጲስ ፡ ቆጶሱ ፡ ፈቃድ ፡ ምንም ፡ ምን ፡ ያደርግ ፡ ዘንድ ፡ እንደማይገባ ፡ ይናገራል ።'),
  ('6d51f407-4a44-568b-a115-fb23a823dc0f', '69d8e037-ce9d-56e6-adb7-75470f7dcd39', 1, 'ኤጲስ ፡ ቆጶሱ ፡ ነገሩን ፡ ሁሉ ፡ በእውነትና ፡ በቅንነት ፡ መርምሮ ፡ ይረዳ ፡ ዘንድ ፡ እንዲገባው ፡ ይናገራል ።'),
  ('19abb181-b435-5447-a975-ca133ad85e95', '05e1d2a8-15b4-57d5-a034-ebe53873d9b0', 1, 'ክርስቲያኖች ፡ ዘወትር ፡ የወንድሞቻቸውን ፡ በደል ፡ ይቅር ፡ ይሉ ፡ ዘንድ ፣ በልቦናቸውም ፡ ቂምን ፡ እንዳያኖሩ ፣ ክፋትንም ፡ እንዳያስቡ ፡ እንደሚገባ ፡ ይናገራል ።'),
  ('be728a34-9f73-50b7-a479-795e2771c1a2', '0578ccd7-9a79-5375-a91e-f97ce87c3fdf', 1, 'ክርስቲያኖች ፡ ጨዋታን ፡ ለማየትና ፡ ዘፈንን ፡ ለመስማት ፡ ወደ ፡ ልዩ ፡ ሕዝብ ፡ ማደሪያ ፡ ይገቡ ፡ ዘንድ ፡ እንዳይገባ ፡ ይናገራል ።'),
  ('8e1a3816-99f8-5a1b-a1f1-df66afba357c', '6feb4a3e-3dbf-5240-a169-ddae787780b0', 1, 'ባል ፡ የሌላቸው ፡ የባልቴቶችን ፡ ነገር ፡ ይናገራል ።'),
  ('14bf9c0f-f78e-5079-a2f2-be9bf19ac73a', '1ec11740-25fe-5c66-ac2c-cbbebfe32858', 1, 'ሴቶች ፡ ያጠምቁ ፡ ዘንድ ፡ እንዳይገባ ፡ ይናገራል ።'),
  ('86bb18b7-0fa3-523c-a80d-9437dbc82738', '61ffb5a9-16eb-5567-afcb-0d9966d5fec4', 1, 'ሕዝባዊ ፡ የክህነትን ፡ ሥራ ፡ ይሠራ ፡ ዘንድ ፡ እንዳይገባው ፡ ይናገራል ።'),
  ('e4bc9fff-9ee9-51e2-ad10-d0525f633849', '8e0ce462-9702-5d13-a6a0-8b8984cf2878', 1, 'የፈትን ፡ ነገር ፡ ይናገራል ፡'),
  ('454ec066-75da-5689-a1dc-4f9beaa1d419', '62de8a02-2ae8-5d2b-ad10-b32ad176f06d', 1, 'አባትና ፡ እናታቸው ፡ ስለሞቱባቸው ፡ ይናገራል ፡'),
  ('6cd0c2c1-9f6d-5916-a3b5-6fd56262c0d3', '665e8aa5-1990-561c-a72f-87db4c389ea6', 1, 'ኤጲስ ፡ ቆጶሳት ፡ አባት ፡ እናት ፡ ስለሞቱባቸው ፡ ልጆችና ፡ ባልቴቶች ፡ ይተክዙ ፡ ዘንድ ፡ አገባብ ፡ እንደሆነ ፡ ይናገራል ።'),
  ('25b3d4f3-b20e-5364-a2e8-73814006a503', 'eeb83760-687e-5af4-ae0b-871f491fd4bb', 1, 'ባሏ ፡ ስለሞተባትና ፡ ባልቴቶች ፡ የሚሰጣቸውን ፡ በምስጋና ፡ ይቀበሉ ፡ ዘንድ ፡ እንደሚገባ ፡ ይናገራል ።'),
  ('2e3cca8e-b29e-5374-a91e-61576bf0c395', 'c64d8710-479e-5414-a73c-6aeedce46e2a', 1, 'ኤጲስ ፡ ቆጶሱ ፡ መስጠት ፡ ከሚገባቸው ፡ ሰዎች ፡ መባ ፡ መቀበልን ፡ ያስተውል ፡ ዘንድ ፡ እንደሚገባ ፡ ይናገራል ።'),
  ('39b1827d-a95b-56a1-a6a4-96848293f924', '72a3e667-6394-5624-a320-6c0ea24a622d', 1, 'አባቶች ፡ ልጆቻቸውን ፡ ይመክሩ ፡ ዘንድ ፡ አገባብ ፡ እንደሆነ ፡ ይናገራል ።'),
  ('17ef5104-6bb7-556b-a0f6-1be39d3ad16f', '9c09a60f-84fa-5b2f-a638-83b8e9e01b3f', 1, 'አገልጋዮች ፡ ለጌቶቻቸው ፡ ከሐዲዎችም ፡ ቢሆኑ ፣ ፡ ምእመናንም ፡ ቢሆኑ ፣ ፡ በፍጹም ፡ ንጽሕና ፡ ትሕትናን ፡ ያደርጉ ፡ ዘንድ ፡ እንዲገባ ፡ ይናገራል ።'),
  ('ebdb011c-939e-532a-a1cd-37d6c64818b4', '6e98023b-be0b-59f9-ac7d-0ee16cbf1b55', 1, 'ደናግል ፡ ሰውነታቸውን ፡ ሳይፈትኑ ፡ ራሳቸውን ፡ ይሃሉ ፡ ዘንድ ፡ እንዳ ፡ ይገባ ፡ ይናገራል ።'),
  ('cc0f84f3-0e14-5b2c-acfe-23797f702f98', 'dd5a559a-4398-5d26-ac16-138d56a83cff', 1, 'ስለ ፡ በዐላትና ፡ ፋሲካ ፡ ወደ ፡ አደባባይ ፡ ወስደው ፡ በጽኑዕ ፡ መከራ ፡ ፍርድ ፡ የሚያስጨንቋቸው ፡ የሰማዕታትን ፡ ነገር ፡ ይናራል ።'),
  ('57b8e76d-5023-54c8-a7c6-3bcc931515f3', '7ce459cd-f137-5398-ac5d-1ad63275606d', 1, 'ስለ ፡ ሙታን ፡ መነሣት ፡ ይናገራል ፡'),
  ('29487071-cb69-5401-accf-3b33e40ca7be', 'df752999-e065-5c47-aa10-bdfca01bbede', 1, 'የሰማዕታትን ፡ ነገር ፡ ይናገራል ።'),
  ('63304f68-6a60-55a3-a4ef-a2998c6f3d5c', '79d06713-ad36-5a20-a96e-114a29756ca4', 1, 'በቤተ ፡ ክርስቲያን ፡ ይዘምሩ ፡ ያመሰግኑ ፡ ዘንድ ፡ ነው ፡ እንጂ ፡ ክርስቲያኖች ፡ ወደ ፡ ዘፈን ፡ ወደ ፡ ጨዋታ ፡ ቤት ፡ ይገቡ ፡ ዘንድ ፡ እንዳይገባ ፡ ይናገራል ።'),
  ('aa1fadb7-55b6-57a0-a777-362cd493863f', '86cab4a9-a386-5a0f-a8d4-b10f269a5faf', 1, 'ክርስቲያን ፡ በጣዖታትና ፡ በአጋንንት ፡ ስም ፡ ይምሉ ፡ ዘንድ ፡ ፈጽመውም ፡ እንደ ፡ ቀድሞው ፡ ልማድ ፡ ስማቸውን ፡ ይጠራቸው ፡ ዘንድ ፡ እንዳይገባ ፡ ይናገራል ።'),
  ('65ab8e9a-e4ac-5435-ac8e-da8dd0e83e34', '3c30fc78-0b75-5a6f-af40-4a73b93c0ec6', 1, 'የበዓላትን ፡ ቀን ፡ በመንፈሳዊ ፡ ደስታ ፡ ይጠብቁ ፡ ዘንድ ፡ እንዲገባ ፡ ይና ፡ ገራል ።'),
